import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to probabilistically determine 
    if an item is in a set. The expected size and false positive rate dictate the 
    bit array size and number of hash functions used.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)

        # Calculate the number of hash functions
        self.num_hashes = self._optimal_number_of_hash_functions(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _hash(self, item: str, seed: int) -> int:
        """Hash the item with a given seed and return an index in the bit array."""
        hash_input = f"{seed}:{item}".encode()
        return int(hashlib.md5(hash_input).hexdigest(), 16) % self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array in bits."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round(m / n * math.log(2)))

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for seed in range(self.num_hashes):
            index = self._hash(item, seed)
            if self.bit_array[index] == 0:
                return False
        return True

