import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a custom array to track 
    bit states for set membership. This design utilizes a unique 
    approach for hashing to increase randomness and utilizes basic 
    array operations to avoid external dependencies.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_hash_count(self.size, expected_items)

        # Initialize a custom bit array to zero
        self.bit_array = [0] * (self.size // 32 + 1)

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Determine the size of the bit array using the expected items and false positive rate."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions required."""
        return max(1, round(m / n * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Create a unique hash for an item based on a seed."""
        hasher = hashlib.sha256()
        hasher.update(f"{item}:{seed}".encode())
        return int(hasher.hexdigest(), 16) % self.size

    def _set_bit(self, index: int) -> None:
        """Set the bit at the given index in the bit array."""
        self.bit_array[index // 32] |= (1 << (index % 32))

    def _check_bit(self, index: int) -> bool:
        """Check the bit at the given index in the bit array."""
        return (self.bit_array[index // 32] & (1 << (index % 32))) != 0

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_index = self._hash(item, i)
            self._set_bit(hash_index)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_index = self._hash(item, i)
            if not self._check_bit(hash_index):
                return False
        return True

